export function parseDelay(value: string): number | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  if (trimmed === "") return null;

  // number followed by optional suffix: "ms" or "s" ("ms" must come first in the
  // alternation so it is not consumed as "s")
  const match = trimmed.match(/^(\d+(?:\.\d+)?|\.\d+)(ms|s)?$/);
  if (!match) return null;

  const num = Number(match[1]);
  if (!Number.isFinite(num)) return null;

  if (match[2] === "s") return num * 1000;
  return num; // "ms" suffix and plain numbers are already milliseconds
}

/**
 * Parse a duration string into milliseconds.
 *
 * Supported formats:
 *   - seconds with "s" suffix:   parseDelay("2s")  === 2000
 *   - milliseconds with "ms":    parseDelay("500ms") === 500
 *   - plain numbers (ms):        parseDelay("100") === 100
 *
 * For invalid input, return null (e.g. parseDelay("abc") === null).
 */
export function parseDelay(value: string): number | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  if (trimmed === "") return null;

  // number followed by optional suffix: "ms" or "s" ("ms" must come first in the
  // alternation so it is not consumed as "s")
  const match = trimmed.match(/^(\d+(?:\.\d+)?|\.\d+)(ms|s)?$/);
  if (!match) return null;

  const num = Number(match[1]);
  if (!Number.isFinite(num)) return null;

  if (match[2] === "s") return num * 1000;
  return num; // "ms" suffix and plain numbers are already milliseconds
}

