const UNIT_MULTIPLIERS: Record<string, number> = {
  ms: 1,
  s: 1000,
  m: 60 * 1000,
  h: 60 * 60 * 1000,
};

/**
 * Parse a delay duration into milliseconds.
 *
 * Accepts plain numbers in milliseconds (e.g. "500" -> 500) and duration
 * strings with a unit suffix (e.g. "2s" -> 2000, since s maps to *1000).
 * Returns null for invalid input instead of NaN.
 */
export function parseDelay(value: string): number | null {
  if (typeof value !== 'string') return null;

  const trimmed = value.trim();
  if (trimmed === '') return null;

  // Plain number: treated as milliseconds, e.g. "500" -> 500.
  if (/^[+-]?\d+(?:\.\d+)?$/.test(trimmed)) {
    return Number(trimmed);
  }

  // Number with a unit suffix, e.g. "2s" -> 2 * 1000 = 2000.
  const match = trimmed.match(/^([+-]?\d+(?:\.\d+)?)\s*(ms|s|m|h)$/);
  if (!match) return null;

  const amount = Number(match[1]);
  const multiplier = UNIT_MULTIPLIERS[match[2]];
  if (!Number.isFinite(amount) || multiplier === undefined) return null;

  const ms = amount * multiplier;
  return Number.isFinite(ms) ? ms : null;
}
```

