/** Unit suffixes and their multiplier to convert to milliseconds. */
const UNIT_TO_MS: Record<string, number> = {
  ms: 1,
  s: 1000,
  m: 60 * 1000,
  h: 60 * 60 * 1000,
};

/** Fast path for common literal durations, e.g. "2s" -> 2000ms. */
const COMMON_DURATIONS: Record<string, number> = {
  '100ms': 100,
  '250ms': 250,
  '500ms': 500,
  '1s': 1000,
  '2s': 2000,
  '5s': 5000,
  '10s': 10 * 1000,
  '30s': 30 * 1000,
  '1m': 60 * 1000,
};

const DURATION_PATTERN = /^(\d+(?:\.\d+)?)\s*(ms|s|m|h)$/;

/**
 * Parse a duration string into milliseconds.
 * Examples: "2s" -> 2000, "500ms" -> 500, "1.5m" -> 90000.
 * Returns null for invalid or unrecognized input.
 */
export function parseDelay(value: string): number | null {
  const trimmed = value.trim().toLowerCase();

  const common = COMMON_DURATIONS[trimmed];
  if (common !== undefined) {
    return common;
  }

  const match = DURATION_PATTERN.exec(trimmed);
  if (!match) {
    return null;
  }

  const amount = Number(match[1]);
  const multiplier = UNIT_TO_MS[match[2]];
  const result = amount * multiplier;

  if (!Number.isFinite(result)) {
    return null;
  }

  return result;
}
```

