/**
 * Parse a delay string into milliseconds.
 *
 * Examples: parseDelay("2s") === 2000, parseDelay("500ms") === 500,
 * parseDelay("1m") === 60000, parseDelay("1h") === 3600000,
 * parseDelay("100") === 100 (bare numbers are milliseconds).
 * Invalid input returns null.
 */
export function parseDelay(value: string): number | null {
  const match = /^\s*(\d+(?:\.\d+)?)\s*(ms|s|m|h)?\s*$/i.exec(value);
  if (!match) {
    return null;
  }
  const amount = Number(match[1]);
  const unit = (match[2] ?? 'ms').toLowerCase();
  const factors: Record<string, number> = {
    ms: 1,
    s: 1000,
    m: 60000,
    h: 3600000,
  };
  return amount * factors[unit];
}

