export function parseDelay(value: string): number | null {
  // Examples: "2s" -> 2000, "500" -> 500, "100ms" -> 100, "3m" -> 180000, "1h" -> 3600000
  const match = /^\s*(\d+(?:\.\d+)?)\s*(ms|s|m|h)?\s*$/.exec(value);
  if (!match) return null;
  const amount = Number(match[1]);
  if (match[2] === undefined) return amount;
  const factors: Record<string, number> = {
    ms: 1,
    s: 1000,
    m: 60000,
    h: 3600000,
  };
  return amount * factors[match[2]];
}
```

