/**
 * Parse a delay string into milliseconds.
 *
 * Accepts an optional unit suffix: "ms", "s", "m", or "h".
 * Plain numbers are treated as milliseconds.
 * Returns null for input that is not a valid delay string.
 *
 * Examples:
 *   parseDelay("2s")    // => 2000
 *   parseDelay("500")   // => 500
 *   parseDelay("1.5m")  // => 90000
 *   parseDelay("2h")    // => 7200000
 *   parseDelay("abc")   // => null
 */
const UNIT_MULTIPLIERS: Record<string, number> = {
  ms: 1,
  s: 1000,
  m: 60 * 1000,
  h: 60 * 60 * 1000,
};

export function parseDelay(value: string): number | null {
  const match = /^(\d+(?:\.\d+)?)\s*(ms|s|m|h)?$/i.exec(value.trim());
  if (!match) {
    return null;
  }

  const amount = Number(match[1]);
  const unit = (match[2] ?? 'ms').toLowerCase();

  return Math.round(amount * UNIT_MULTIPLIERS[unit]);
}

