/**
 * Parse a delay string into milliseconds.
 *
 * Supported formats: bare numbers ("250" -> 250) and unit suffixes:
 * "ms", "s", "m" (e.g. parseDelay("2s") === 2000).
 * Empty or whitespace-only input returns 0. Invalid input returns null.
 */
export function parseDelay(value: string): number | null {
  const trimmed = value.trim();
  if (trimmed === '') return 0;

  const match = /^(\d+(?:\.\d+)?)(ms|s|m)?$/.exec(trimmed);
  if (!match) return null;

  const amount = Number(match[1]);
  const unit = match[2] ?? 'ms';
  const multiplier: Record<string, number> = { ms: 1, s: 1000, m: 60000 };

  return amount * multiplier[unit];
}

