export function parseDelay(value: string): number | null {
  const match = /^\s*(\d+)(ms|s|m)?\s*$/.exec(value);
  if (!match) {
    return null;
  }

  const amount = Number(match[1]);
  const suffix = match[2];

  switch (suffix) {
    case 'ms':
      return amount;
    case 's':
      return amount * 1000;
    case 'm':
      return amount * 60000;
    default:
      return amount;
  }
}

/**
 * Parse a delay string into milliseconds.
 *
 * Supports time-suffixed values as well as plain numbers:
 * - `parseDelay("2s")` returns `2000`
 * - `parseDelay("500ms")` returns `500`
 * - `parseDelay("1m")` returns `60000`
 * - `parseDelay("300")` returns `300`
 *
 * Invalid input (e.g. `"abc"`, `""`, or an unmatched suffix like `"2x"`)
 * returns `null`.
 */
export function parseDelay(value: string): number | null {
  const match = /^\s*(\d+)(ms|s|m)?\s*$/.exec(value);
  if (!match) {
    return null;
  }

  const amount = Number(match[1]);
  const suffix = match[2];

  switch (suffix) {
    case 's':
      return amount * 1000;
    case 'm':
      return amount * 60000;
    default:
      // "ms" and no suffix both map to milliseconds as-is
      return amount;
  }
}

