/**
 * Parse a delay string into milliseconds.
 * Supports unit suffixes "ms", "s" (seconds), "m" (minutes), "h" (hours),
 * and bare numbers (treated as milliseconds).
 * Examples: parseDelay("2s") === 2000, parseDelay("500ms") === 500,
 *           parseDelay("300") === 300, parseDelay("5m") === 300000,
 *           parseDelay("1h") === 3600000.
 * Returns null for invalid or unparseable input (e.g. "abc", "", "2x").
 */
export function parseDelay(value: string): number | null {
  const match = /^\s*(\d+(?:\.\d+)?)\s*(ms|s|m|h)?\s*$/.exec(value);
  if (!match) {
    return null;
  }
  const amount = Number(match[1]);
  switch (match[2]) {
    case 's':
      return amount * 1000;
    case 'm':
      return amount * 60000;
    case 'h':
      return amount * 3600000;
    case 'ms':
    default:
      return amount;
  }
}
```

