export function parseDelay(value: string): number | null {
  const trimmed = value.trim();

  // Plain number: pass through as-is, e.g. "1500" -> 1500.
  const asNumber = Number(trimmed);
  if (trimmed !== "" && !Number.isNaN(asNumber)) {
    return asNumber;
  }

  // Seconds suffix: "2s" -> 2000 milliseconds.
  const match = trimmed.match(/^(\d+(?:\.\d+)?)s$/);
  if (match) {
    return Number(match[1]) * 1000;
  }

  // Invalid/unparseable input returns null instead of NaN.
  return null;
}

