const DURATION_RE = /^(\d+(?:\.\d+)?)(ms|s|m|h)?$/;

const UNIT_MULTIPLIERS: Record<string, number> = {
  ms: 1,
  s: 1000,
  m: 60_000,
  h: 3_600_000,
};

export function parseDelay(value: string): number | null {
  const match = DURATION_RE.exec(value.trim());
  if (!match) {
    return null;
  }

  const amount = Number(match[1]);
  if (!Number.isFinite(amount)) {
    return null;
  }

  const unit = match[2] ?? 'ms';
  return amount * UNIT_MULTIPLIERS[unit];
}

/**
 * Parse a duration string into milliseconds.
 *
 * Examples:
 *   parseDelay("2s")    // 2000
 *   parseDelay("500ms") // 500
 *   parseDelay("1m")    // 60000
 *   parseDelay("100")   // 100 (plain numbers are milliseconds)
 *
 * Returns null for invalid input (non-numeric or unparseable strings).
 */
const DURATION_RE = /^(\d+(?:\.\d+)?)(ms|s|m|h)?$/;

const UNIT_MULTIPLIERS: Record<string, number> = {
  ms: 1,
  s: 1000,
  m: 60_000,
  h: 3_600_000,
};

export function parseDelay(value: string): number | null {
  const match = DURATION_RE.exec(value.trim());
  if (!match) {
    return null;
  }

  const amount = Number(match[1]);
  if (!Number.isFinite(amount)) {
    return null;
  }

  const unit = match[2] ?? 'ms';
  return amount * UNIT_MULTIPLIERS[unit];
}

