export function parseDelay(value: string): number | null {
  const trimmed = value.trim();
  const match = /^(\d+(?:\.\d+)?)(ms|s)?$/.exec(trimmed);
  if (!match) {
    return null;
  }
  const amount = Number(match[1]);
  const unit = match[2];
  if (!Number.isFinite(amount) || amount <= 0) {
    return null;
  }
  if (unit === "s") {
    return amount * 1000;
  }
  return amount;
}

/**
 * Parse a delay string into milliseconds.
 *
 * Examples: parseDelay("2s") -> 2000, parseDelay("500ms") -> 500.
 * Invalid or non-positive input returns null.
 */
export function parseDelay(value: string): number | null {
  const trimmed = value.trim();
  const match = /^(\d+(?:\.\d+)?)(ms|s)?$/.exec(trimmed);
  if (!match) {
    return null;
  }
  const amount = Number(match[1]);
  const unit = match[2];
  if (!Number.isFinite(amount) || amount <= 0) {
    return null;
  }
  if (unit === "s") {
    return amount * 1000;
  }
  return amount;
